import { MakeLogicType, afterMount, connect, kea, listeners, path, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'

import { actionsModel } from '~/models/actionsModel'
import { ActionType, EventDefinitionType } from '~/types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface conversionGoalOptionsLogicValues {
    actions: ActionType[] // actionsModel
    actionsLoaded: boolean // actionsModel
    customEventCount: number | null
    customEventCountLoading: boolean
    hasNoConversionGoalOptions: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface conversionGoalOptionsLogicActions {
    loadActionsSuccess: (
        actions: ActionType[],
        payload?: any
    ) => {
        actions: ActionType[]
        payload?: any
    } // actionsModel
    loadCustomEventCount: () => any
    loadCustomEventCountFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadCustomEventCountSuccess: (
        customEventCount: number,
        payload?: any
    ) => {
        customEventCount: number
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface conversionGoalOptionsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        hasNoConversionGoalOptions: (
            actionsLoaded: boolean,
            actions: ActionType[],
            customEventCount: number | null
        ) => boolean
    }
}

export type conversionGoalOptionsLogicType = MakeLogicType<
    conversionGoalOptionsLogicValues,
    conversionGoalOptionsLogicActions,
    Record<string, any>,
    conversionGoalOptionsLogicMeta
>

/** Tells the conversion goal picker whether the project has anything it can offer as a goal. */
export const conversionGoalOptionsLogic = kea<conversionGoalOptionsLogicType>([
    path(['scenes', 'web-analytics', 'conversionGoalOptionsLogic']),
    connect(() => ({
        values: [actionsModel, ['actions', 'actionsLoaded']],
        actions: [actionsModel, ['loadActionsSuccess']],
    })),
    loaders({
        customEventCount: [
            null as number | null,
            {
                loadCustomEventCount: async () => {
                    const response = await api.eventDefinitions.list({
                        limit: 1,
                        event_type: EventDefinitionType.EventCustom,
                        // Same filter the picker's Custom Events list uses, so a project whose
                        // custom events are all hidden counts as having none.
                        exclude_hidden: true,
                    })
                    return response.count ?? 0
                },
            },
        ],
    }),
    selectors({
        hasNoConversionGoalOptions: [
            (s) => [s.actionsLoaded, s.actions, s.customEventCount],
            // Stays false until both counts arrive, so the picker does not flash a zero state on load.
            (actionsLoaded: boolean, actions: ActionType[], customEventCount: number | null) =>
                actionsLoaded && customEventCount !== null && actions.length === 0 && customEventCount === 0,
        ],
    }),
    // The count only changes the answer when the project has no actions, and the event definitions
    // endpoint counts by loading every matching row. So ask for it only when it can matter.
    listeners(({ actions, values }) => ({
        loadActionsSuccess: () => {
            if (values.actions.length === 0) {
                actions.loadCustomEventCount()
            }
        },
    })),
    afterMount(({ actions, values }) => {
        // actionsModel stays mounted between scenes, so a later visit finds it loaded and
        // dispatches no success for the listener above to catch.
        if (values.actionsLoaded && values.actions.length === 0) {
            actions.loadCustomEventCount()
        }
    }),
])
